package com.simibubi.create.content.trains.track;

import com.simibubi.create.foundation.utility.LoadedLevelAccess;
import it.unimi.dsi.fastutil.longs.Long2ObjectLinkedOpenHashMap;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BarrelBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.*;
import net.minecraft.world.level.chunk.status.ChunkStatus;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.phys.Vec3;

/** Proposed real native planner/createPortal comparisons. No transaction/auto-generation success is claimed. */
public final class NetherPortalFramePlanGameTests {
    private static final String STRUCTURE="create_test:reservoir";
    private static final AtomicInteger NEXT=new AtomicInteger();
    private record Fixture(ServerLevel level,BlockPos search){}
    private static Fixture fixture(GameTestHelper h){
        int index=NEXT.incrementAndGet();var level=h.getLevel().getServer().getLevel(Level.NETHER);h.assertTrue(level!=null,"Actual native Nether must exist");var search=new BlockPos(600_008+index*2048,90,160_008);var cp=ChunkPos.containing(search);
        // Actual native chunk fixture preparation is deliberately outside measured planning scope.
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)level.getChunk(cp.x()+x,cp.z()+z);
        return new Fixture(level,search);
    }
    private static NetherPortalFramePlan plan(GameTestHelper h,Fixture f,Direction.Axis axis){var value=NetherPortalFramePlan.find(f.level(),f.search(),axis);h.assertTrue(value.isPresent(),"Actual vanilla Nether height permits a native frame plan");return value.get();}
    private static void nativeComparison(GameTestHelper h,Fixture f,Direction.Axis axis,boolean expectFallback){
        var plan=plan(h,f,axis);if(expectFallback)h.assertTrue(plan.fallback(),"Actual bounded real terrain leaves no native corridor and must use fallback");var desired=new LinkedHashMap<BlockPos,BlockState>();for(var write:plan.writes())desired.put(write.position(),write.state());
        var result=f.level().getPortalForcer().createPortal(f.search(),axis);h.assertTrue(result.isPresent()&&result.get().minCorner.equals(plan.rectangle().minCorner)&&result.get().axis1Size==plan.rectangle().axis1Size&&result.get().axis2Size==plan.rectangle().axis2Size,"Actual native createPortal chooses same rectangle/axis dimensions as read-only native selection");
        for(var entry:desired.entrySet())h.assertTrue(f.level().getBlockState(entry.getKey())==entry.getValue(),"Actual native generated frame/interior matches exact planned final world state at "+entry.getKey());
    }
    private static Map<Long,List<String>> tickets(ServerLevel level){
        try{var field=ServerChunkCache.class.getDeclaredField("ticketStorage");field.setAccessible(true);var storage=(TicketStorage)field.get(level.getChunkSource());var map=TicketStorage.class.getDeclaredField("tickets");map.setAccessible(true);var real=(it.unimi.dsi.fastutil.longs.Long2ObjectMap<List<Ticket>>)map.get(storage);var result=new TreeMap<Long,List<String>>();for(var entry:real.long2ObjectEntrySet())result.put(entry.getLongKey(),entry.getValue().stream().map(Ticket::toString).toList());return result;}
        catch(ReflectiveOperationException error){throw new AssertionError("Native ticket audit API changed",error);}
    }
    private static boolean refuses(Runnable operation){try{operation.run();return false;}catch(IllegalStateException known){return true;}}
    @GameTest(structure=STRUCTURE)public void actualNativeXAxisFrameSelectionMatchesVanillaCreatePortal(GameTestHelper h){nativeComparison(h,fixture(h),Direction.Axis.X,false);h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualNativeZAxisFrameSelectionMatchesVanillaCreatePortal(GameTestHelper h){nativeComparison(h,fixture(h),Direction.Axis.Z,false);h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualFramePlanningAddsNoNativeTicketOrWorldWrite(GameTestHelper h){var f=fixture(h);var tickets=tickets(f.level());int chunks=f.level().getChunkSource().getLoadedChunksCount();var plan=plan(h,f,Direction.Axis.Z);for(var entry:plan.readStates().entrySet())h.assertTrue(TrackPortalAccess.state(f.level(),entry.getKey())==entry.getValue(),"Actual planner state observations remain genuine unchanged native world");plan.requireUnchanged();h.assertTrue(tickets.equals(tickets(f.level()))&&chunks==f.level().getChunkSource().getLoadedChunksCount(),"Read-only frame/heightmap discovery creates no UNKNOWN/PORTAL/FORCED ticket or chunk");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualChangedNativeReadStateInvalidatesPlanBeforeWorldWrites(GameTestHelper h){var f=fixture(h);var plan=plan(h,f,Direction.Axis.X);var entry=plan.readStates().entrySet().iterator().next();var original=entry.getValue();var changed=original.is(Blocks.GLASS)?Blocks.STONE.defaultBlockState():Blocks.GLASS.defaultBlockState();f.level().setBlock(entry.getKey(),changed,Block.UPDATE_ALL);h.assertTrue(refuses(plan::requireUnchanged)&&f.level().getBlockState(entry.getKey())==changed,"A genuine native callback/world state change invalidates stale read plan and is not overwritten");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualHeightmapChangeOutsideLogicalSearchInvalidatesNativePlan(GameTestHelper h){var f=fixture(h);var plan=plan(h,f,Direction.Axis.Z);var old=f.level().getChunkSource().getChunkNow(f.search().getX()>>4,f.search().getZ()>>4).getHeight(Heightmap.Types.MOTION_BLOCKING,f.search().getX()&15,f.search().getZ()&15);var high=f.search().atY(f.level().getMaxY());h.assertTrue(old<f.level().getMaxY(),"Actual generated Nether column has genuine space above logical roof");f.level().setBlock(high,Blocks.OBSIDIAN.defaultBlockState(),Block.UPDATE_ALL);h.assertTrue(refuses(plan::requireUnchanged)&&f.level().getBlockState(high).is(Blocks.OBSIDIAN),"Actual heightmap input change cannot be hidden behind stale native read geometry or rollback");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualNativeFallbackFootprintAndRectangleMatchVanilla(GameTestHelper h){var f=fixture(h);int ceiling=Math.min(f.level().getMaxY(),f.level().getMinY()+f.level().getLogicalHeight()-1);
        // Real native bedrock slices cap every actual free run below four blocks; no fake terrain.
        for(int x=-16;x<=16;x++)for(int z=-16;z<=16;z++)for(int y=f.level().getMinY();y<=ceiling;y+=4)f.level().setBlock(new BlockPos(f.search().getX()+x,y,f.search().getZ()+z),Blocks.BEDROCK.defaultBlockState(),18);
        var plan=plan(h,f,Direction.Axis.Z);h.assertTrue(plan.fallback()&&plan.writes().size()==44&&plan.writePositions().size()==36,"Actual source fallback retains24platform/clear then14frame then6portal native writes and their real overlaps");nativeComparison(h,f,Direction.Axis.Z,true);h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualNativeFrameFloorContainerIsRejectedWithOriginalNamedCargo(GameTestHelper h){var f=fixture(h);var initial=plan(h,f,Direction.Axis.X);var corner=initial.rectangle().minCorner;var at=corner.below();f.level().setBlock(at,Blocks.BARREL.defaultBlockState(),Block.UPDATE_ALL);var barrel=(BarrelBlockEntity)LoadedLevelAccess.blockEntity(f.level(),at);var cargo=new ItemStack(Items.DIAMOND,7);cargo.set(DataComponents.CUSTOM_NAME,Component.literal("Seven original native portal frame diamonds"));barrel.setItem(0,cargo);var plan=plan(h,f,Direction.Axis.X);h.assertTrue(plan.writePositions().contains(at),"Native solid floor/container still qualifies for the genuine selected frame footprint");h.assertTrue(refuses(plan::requireNoBlockEntityWrites)&&TrackBlockEntityAccess.existing(f.level(),at)==barrel&&barrel.getItem(0)==cargo,"Explicit frame cargo preflight protects exact actual BE and original item object without running native destructive fallback");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualPendingNativeContainerCannotBecomeEmptyOwnerDuringFramePreflight(GameTestHelper h){var f=fixture(h);var initial=plan(h,f,Direction.Axis.Z);var at=initial.rectangle().minCorner.below();f.level().setBlock(at,Blocks.BARREL.defaultBlockState(),Block.UPDATE_ALL);var barrel=(BarrelBlockEntity)LoadedLevelAccess.blockEntity(f.level(),at);var cargo=new ItemStack(Items.EMERALD,5);cargo.set(DataComponents.CUSTOM_NAME,Component.literal("Five original pending frame emeralds"));barrel.setItem(0,cargo);var saved=barrel.saveWithFullMetadata(f.level().registryAccess());var chunk=f.level().getChunkSource().getChunkNow(at.getX()>>4,at.getZ()>>4);f.level().removeBlockEntity(at);chunk.setBlockEntityNbt(saved);var plan=plan(h,f,Direction.Axis.Z);h.assertTrue(plan.writePositions().contains(at)&&refuses(plan::requireNoBlockEntityWrites)&&!chunk.getBlockEntities().containsKey(at)&&chunk.getBlockEntityNbt(at)==saved,"Actual pending native BE state/NBT is rejected without constructing an empty ready cargo owner");var restored=(BarrelBlockEntity)TrackBlockEntityAccess.existing(f.level(),at);h.assertTrue(restored!=null&&restored.getItem(0).getCount()==5&&restored.getItem(0).has(DataComponents.CUSTOM_NAME),"Only actual native pending-NBT promotion restores original cargo data");h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualMissingNativeHeightmapChunkDefersWithoutLoadingOrTickets(GameTestHelper h){var f=fixture(h);var before=tickets(f.level());unavailable(h,f.level(),f.search(),()->{boolean unknown=false;try{NetherPortalFramePlan.find(f.level(),f.search(),Direction.Axis.X);}catch(UnloadedTrackException missing){unknown=true;}h.assertTrue(unknown&&before.equals(tickets(f.level())),"Actual unavailable native heightmap/search frontier remains unknown with unchanged real native ticket storage");});h.succeed();}
    @GameTest(structure=STRUCTURE)public void actualContainerInsertedAfterPlanningCannotBeErasedByStalePreflight(GameTestHelper h){var f=fixture(h);var plan=plan(h,f,Direction.Axis.X);var at=plan.rectangle().minCorner.below();f.level().setBlock(at,Blocks.BARREL.defaultBlockState(),Block.UPDATE_ALL);var barrel=(BarrelBlockEntity)LoadedLevelAccess.blockEntity(f.level(),at);var cargo=new ItemStack(Items.EMERALD,9);cargo.set(DataComponents.CUSTOM_NAME,Component.literal("Nine original late frame emeralds"));barrel.setItem(0,cargo);h.assertTrue(refuses(plan::requireNoBlockEntityWrites)&&TrackBlockEntityAccess.existing(f.level(),at)==barrel&&barrel.getItem(0)==cargo,"Actual native owner/cargo inserted after selection invalidates stale world plan before any destructive frame write");h.succeed();}
    @SuppressWarnings("unchecked")private static void unavailable(GameTestHelper h,ServerLevel level,BlockPos absent,Runnable body){
        var source=level.getChunkSource();var originalChunk=source.getChunkNow(absent.getX()>>4,absent.getZ()>>4);h.assertTrue(originalChunk!=null,"Native frontier fixture starts with actual FULL chunk");
        try{var field=ChunkMap.class.getDeclaredField("visibleChunkMap");field.setAccessible(true);var original=(Long2ObjectLinkedOpenHashMap<ChunkHolder>)field.get(source.chunkMap);var temporary=original.clone();temporary.remove(ChunkPos.pack(absent.getX()>>4,absent.getZ()>>4));var pf=ServerChunkCache.class.getDeclaredField("lastChunkPos");var sf=ServerChunkCache.class.getDeclaredField("lastChunkStatus");var cf=ServerChunkCache.class.getDeclaredField("lastChunk");pf.setAccessible(true);sf.setAccessible(true);cf.setAccessible(true);var positions=(long[])pf.get(source);var statuses=(ChunkStatus[])sf.get(source);var chunks=(ChunkAccess[])cf.get(source);var oldP=positions.clone();var oldS=statuses.clone();var oldC=chunks.clone();var clear=ServerChunkCache.class.getDeclaredMethod("clearCache");clear.setAccessible(true);
            try{field.set(source.chunkMap,temporary);clear.invoke(source);h.assertTrue(source.getChunkNow(absent.getX()>>4,absent.getZ()>>4)==null,"Actual native map exposes missing planner frontier");body.run();h.assertTrue(source.getChunkNow(absent.getX()>>4,absent.getZ()>>4)==null,"Native frame planner never forces actual missing chunk");}finally{field.set(source.chunkMap,original);System.arraycopy(oldP,0,positions,0,positions.length);System.arraycopy(oldS,0,statuses,0,statuses.length);System.arraycopy(oldC,0,chunks,0,chunks.length);}h.assertTrue(field.get(source.chunkMap)==original&&source.getChunkNow(absent.getX()>>4,absent.getZ()>>4)==originalChunk,"Exact original native chunk map/cache identity restored synchronously");
        }catch(ReflectiveOperationException error){throw new AssertionError("Native planner frontier fixture API changed",error);}
    }
}
